-- ── AI Automation (RT-AIA) ────────────────────────────────────────
INSERT INTO domains (id, title, icon, description, is_active) VALUES
  ('99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'AI Automation', '🤖', 'Design, build and run AI-powered workflows that a Nigerian business can trust: from mapping the process to handing over a monitored, documented automation. 10 weeks, 3 live sessions a week. For: Operations staff, SME owners, virtual assistants, analysts. No coding needed; comfort with Google Sheets helps.', true)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, icon = EXCLUDED.icon,
  description = EXCLUDED.description, is_active = EXCLUDED.is_active;

INSERT INTO modules (id, domain_id, title, description, tool, order_index) VALUES
  ('d73ac98b-f645-5f58-bafa-5db15dcb3016', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Automation thinking and ROI', 'Covers: Map a process end to end (swimlanes); Choose what to automate: rules vs AI vs leave it manual; Estimate hours saved and cost per run. Deliverable: Process audit and ROI sheet for a real business.', 'AI', 1),
  ('98fef27d-195a-5415-b738-03bdba2584d8', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'LLMs for workflows', 'Covers: Tokens, context windows, temperature; Structured output (JSON) and prompt templates; Why models hallucinate and how to check them. Deliverable: Prompt library with a 10-case test sheet.', 'AI', 2),
  ('e04a008f-8ed5-5c7c-ab35-23589462cccd', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'n8n fundamentals', 'Covers: Triggers, nodes, expressions, data mapping; Credentials and connecting Gmail and Sheets; Branching, loops, merging data. Deliverable: Lead capture → Sheet → auto-reply workflow.', 'n8n', 3),
  ('a3684bc6-bebe-59b8-9fe5-cafbb53b9471', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'APIs, webhooks and JSON', 'Covers: HTTP requests, API keys, OAuth; Pagination and rate limits; Paystack / Flutterwave webhook events. Deliverable: Payment confirmation and receipt flow.', 'APIs', 4),
  ('8bf88f0e-ef4d-5d85-ba24-9620645d5562', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'AI inside workflows', 'Covers: Classify, extract, summarise; Invoices and CVs into structured data; Human-in-the-loop approval steps. Deliverable: Invoice extractor with a review queue.', 'n8n', 5),
  ('ebaac240-048d-5902-9edf-83ffe1abfc61', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Messaging bots', 'Covers: WhatsApp Business and Telegram bots; Conversation memory and state; Handover to a human agent. Deliverable: Customer-service bot for an SME.', 'n8n', 6),
  ('4e477de5-e739-5dd7-92bc-915968e9c4f5', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Knowledge bots (RAG)', 'Covers: Chunking, embeddings, vector search; Answering with citations; When RAG fails, and how to detect it. Deliverable: Policy Q&A bot with cited answers.', 'AI', 7),
  ('07817067-3290-506f-b184-f520afeebac3', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Agents and tools', 'Covers: Tool calling and MCP basics; Bounded permissions and guardrails; Why errors compound across steps. Deliverable: Research agent with restricted tools.', 'AI', 8),
  ('9468168c-acf0-50c9-ac14-3f61246b2bc2', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Making it reliable', 'Covers: Error handling, retries, alerts; Logging and golden test sets (evals); Cost monitoring; NDPA 2023 and credential security. Deliverable: Reliability report: test results, failure log, cost per run.', 'n8n', 9),
  ('205ce297-94af-5bc8-909d-4e3fb98b4035', '99cdd084-39ff-56a0-88cf-f2c16aa5c92a', 'Capstone and career', 'Covers: Build for a real SME client; SOP and handover documentation; Pricing and proposals for automation services. Deliverable: Client handover pack + freelance proposal.', 'Capstone', 10)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
  tool = EXCLUDED.tool, order_index = EXCLUDED.order_index;

