INSERT INTO modules (id, domain_id, title, description, tool, order_index) VALUES
  ('8f750091-9fe2-5153-84cd-17549264a275', '9602be95-ac23-58da-9590-c9abdc504473', 'Setup and first programs', 'Covers: Install Python, VS Code, Git; Variables, types, input/output; First GitHub commit. Deliverable: Unit converter on GitHub.', 'Python', 1),
  ('2ec1b196-c886-5767-8c68-f93ce3468386', '9602be95-ac23-58da-9590-c9abdc504473', 'Control flow and debugging', 'Covers: if/elif, for, while; Breaking problems into steps; Using the debugger and reading tracebacks. Deliverable: Exam-grade calculator.', 'Python', 2),
  ('a91dfb45-07f4-535d-8a67-87dd0f3b892c', '9602be95-ac23-58da-9590-c9abdc504473', 'Data structures', 'Covers: Lists, tuples, dicts, sets; Comprehensions; Choosing the right structure. Deliverable: Contact book.', 'Python', 3),
  ('194b6a2f-f4b4-5ed1-a01d-1206df00b6d4', '9602be95-ac23-58da-9590-c9abdc504473', 'Functions and modules', 'Covers: Parameters, returns, scope; Docstrings and type hints; Standard library tour. Deliverable: Reusable utilities module.', 'Python', 4),
  ('3b820b9a-931d-55e3-a789-7b9bb5419dba', '9602be95-ac23-58da-9590-c9abdc504473', 'Files and errors', 'Covers: CSV and JSON files; Exceptions and pathlib; Logging. Deliverable: Expense tracker CLI (mid-course project).', 'Python', 5),
  ('f4fcdc55-a689-57d3-a4e5-a179d208e338', '9602be95-ac23-58da-9590-c9abdc504473', 'Object-oriented Python', 'Covers: Classes, methods, inheritance; Dataclasses; When not to use OOP. Deliverable: Inventory system for a shop.', 'Python', 6),
  ('73b34a6b-b88e-5bac-a47b-cd3258b864e4', '9602be95-ac23-58da-9590-c9abdc504473', 'Testing and clean code', 'Covers: pytest and test-first habits; ruff linting, virtual environments; Code review etiquette. Deliverable: Test suite at 80% coverage.', 'Python', 7),
  ('92bdf69e-61c6-5d72-9839-1c741bef8a89', '9602be95-ac23-58da-9590-c9abdc504473', 'Talking to the web', 'Covers: requests and REST APIs; Scraping responsibly with BeautifulSoup; Handling failures and timeouts. Deliverable: Exchange-rate tracker using a public API.', 'Python', 8),
  ('e13f9c61-1ec7-599b-8cd3-095118dd374d', '9602be95-ac23-58da-9590-c9abdc504473', 'Data with pandas', 'Covers: Load, clean, group, merge; Charts with matplotlib; Excel in and out. Deliverable: NBS dataset analysis notebook.', 'Python', 9),
  ('b0e99738-d423-5da6-aca9-d5f67cefeca7', '9602be95-ac23-58da-9590-c9abdc504473', 'Databases and APIs', 'Covers: SQL basics with SQLite; Building a CRUD API with FastAPI; Environment variables and secrets. Deliverable: Mini booking API.', 'SQL', 10),
  ('38a30237-ecbd-5ecf-b62e-72a7d163704d', '9602be95-ac23-58da-9590-c9abdc504473', 'Automation and AI-assisted coding', 'Covers: Scheduling scripts, emailing reports; Using AI assistants: prompt, review, test; Explaining generated code line by line. Deliverable: Automated weekly report bot + AI-use log.', 'Python', 11),
  ('d887d92f-ceb1-50e2-844c-b1b3d0c31acc', '9602be95-ac23-58da-9590-c9abdc504473', 'Capstone and career', 'Covers: Deploy to a free host; README and project docs; Mock technical interview and live coding. Deliverable: Deployed app + interview recording.', 'Capstone', 12)
