-- ── Public Health Data Analytics (RT-HDA) ────────────────────────────────────────
INSERT INTO domains (id, title, icon, description, is_active) VALUES
  ('c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Public Health Data Analytics', '🏥', 'Turn routine health data into decisions: quality-checked DHIS2 data, indicator dashboards, and briefs that programme managers actually act on. 10 weeks, 3 live sessions a week. For: Health information officers, M&E officers, nurses, CHEWs, public-health graduates, NGO programme staff.', true)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, icon = EXCLUDED.icon,
  description = EXCLUDED.description, is_active = EXCLUDED.is_active;

INSERT INTO modules (id, domain_id, title, description, tool, order_index) VALUES
  ('4a7b0861-b0dc-5b17-bcff-30664046781a', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'The Nigerian health data landscape', 'Covers: NHMIS, DHIS2, EMRs, NDHS, MICS, NHIA claims; Key indicators: ANC4, Penta3, skilled birth attendance; Confidentiality and NDPA 2023. Deliverable: Indicator reference sheet for one programme.', 'Health Data', 1),
  ('e8bda13b-dbe8-5d0a-82e3-d8a45df36a90', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Excel for health data', 'Covers: Cleaning facility reports; Lookups and pivots; Numerators, denominators and target populations. Deliverable: LGA indicator workbook.', 'Excel', 2),
  ('c43a5b51-111e-55db-94ca-ba8e06efcd51', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Collecting good data', 'Covers: Designing ODK/Kobo forms with validation; DHIS2 data entry, pivot tables, data visualiser; Preventing errors at the source. Deliverable: Validated survey form + DHIS2 pivot.', 'DHIS2', 3),
  ('b2ed1528-2041-5dda-b242-286086f1b79d', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Data quality assurance', 'Covers: Completeness, timeliness, consistency; Outliers and internal consistency checks; RDQA / WHO DQR methods, triangulation. Deliverable: DQA report for a synthetic state dataset.', 'DHIS2', 4),
  ('61c3c001-cd7c-544f-a706-6ce818d5efe1', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'SQL for health datasets', 'Covers: Patient and facility tables; Joins, cohorts, aggregations; Tracking clients over time. Deliverable: Cohort retention query set.', 'SQL', 5),
  ('bc64893c-eb2c-55e9-856c-ad67aea5d1d6', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Epidemiology and biostatistics', 'Covers: Rates, ratios, incidence, prevalence; Confidence intervals and chi-square; Trends and seasonality, in JMP. Deliverable: Outbreak trend analysis (mid-course project).', 'JMP', 6),
  ('d68f9a1e-b6f8-5e82-a60f-440a9df118de', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Power BI health dashboards', 'Covers: Data model for facility × month × indicator; DAX for coverage and target vs achievement; Drill-down from state to LGA to facility. Deliverable: Programme dashboard.', 'Power BI', 7),
  ('0f566943-bd0b-595e-bf29-a75740ce9d1c', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Mapping and equity', 'Covers: Mapping by LGA and ward; Coverage gaps and catchment areas; Equity: who is being missed. Deliverable: Coverage gap map.', 'Power BI', 8),
  ('ba70a2e8-2a67-5655-8189-4dc879963deb', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'M&E reporting and data use', 'Covers: Logframes and indicator frameworks; Writing a 2-page data brief; Running a data review meeting. Deliverable: Data brief for a programme manager.', 'Health Data', 9),
  ('b728c231-0331-503a-b4b1-7f4ee2b7e2bc', 'c321ec38-0ac6-5cef-921a-3ba3682f81b4', 'Capstone and career', 'Covers: State routine-data analysis end to end; Panel presentation to programme managers; CV, LinkedIn and M&E interview practice. Deliverable: Capstone pack + policy brief.', 'Capstone', 10)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description,
  tool = EXCLUDED.tool, order_index = EXCLUDED.order_index;

