INSERT INTO domains (id, title, icon, description, is_active) VALUES
  ('f360d6c9-59d4-5594-a54b-602093235fda', 'Data Analysis for Engineers', '⚙️', 'Analyse sensor, process and maintenance data the way plants and utilities need it: SPC, experiments, reliability and early warning of failures. 10 weeks, 3 live sessions a week. For: Mechanical, electrical, civil, chemical and petroleum engineers; maintenance planners; quality and process engineers.', true)
