INSERT INTO modules (id, domain_id, title, description, tool, order_index) VALUES
  ('a1ebe188-bef2-5dad-878b-4490421e1544', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Engineering data foundations', 'Covers: Data from SCADA, PLCs, sensors, lab tests; Units, sampling rates and measurement error; Engineering calculations in Excel. Deliverable: Cleaned sensor log with unit checks.', 'Excel', 1),
  ('9029f79e-75c2-5f77-a5a3-cebb5c246015', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Python for engineers', 'Covers: NumPy and pandas; Reading historian and CSV exports; Plotting with matplotlib. Deliverable: Generator run-hours analysis notebook.', 'Python', 2),
  ('632e0c85-a59a-5a7b-85d9-c4799ee92d26', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Statistics for engineering', 'Covers: Distributions and uncertainty; Hypothesis tests and regression; Measurement system analysis (Gage R&R). Deliverable: Gage R&R study in JMP.', 'JMP', 3),
  ('0e4d3c17-0b0a-503a-8ebe-23c085783316', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Statistical process control', 'Covers: X̄-R, I-MR and p charts; Cp / Cpk process capability; Western Electric rules. Deliverable: SPC report on a production line (mid-course project).', 'JMP', 4),
  ('88480a86-3408-5a40-b5c3-24acd2c1f85b', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Design of experiments', 'Covers: Full and fractional factorials; Response surfaces; Optimising a process setting. Deliverable: DOE study in JMP.', 'JMP', 5),
  ('86c059b8-e6b0-5ee9-8b87-777369795c5a', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Time series and signals', 'Covers: Resampling and smoothing; Trend and seasonality; FFT basics for vibration data. Deliverable: Vibration spectrum analysis.', 'Python', 6),
  ('88d752d2-cc6b-5ecb-999b-b0ab8215f3f2', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Reliability and maintenance', 'Covers: MTBF, MTTR, availability, OEE; Weibull analysis; Failure modes and Pareto. Deliverable: Asset reliability scorecard.', 'JMP', 7),
  ('980e8694-00cf-5264-9266-3b25269b7987', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Anomaly detection and predictive maintenance', 'Covers: Feature extraction; Thresholds vs isolation forest; Remaining useful life concept. Deliverable: Early-warning model.', 'Python', 8),
  ('6b274c67-0309-50f8-b8a1-eca7fac90ce0', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Operations dashboards and reporting', 'Covers: Operations KPIs in Power BI: OEE, downtime, energy; Writing engineering recommendations; Costing downtime and maintenance options. Deliverable: Operations dashboard.', 'Power BI', 9),
  ('5cbae9ed-f2b6-55d4-bd3b-e741a7ea5fe2', 'f360d6c9-59d4-5594-a54b-602093235fda', 'Capstone and career', 'Covers: Asset dataset analysis end to end; Presenting to plant management; CV, LinkedIn and technical interview practice. Deliverable: Capstone report + recommendation memo.', 'Capstone', 10)
