INSERT INTO domains (id, title, icon, description, is_active) VALUES
  ('85eebe54-039a-56e2-8b66-223a25df396a', 'Cyber Security', '🛡️', 'A lab-first path to SOC Analyst (Tier 1) and junior security roles, aligned to Security+ and ISC2 CC, with every skill evidenced in a portfolio. 16 weeks, 3 live sessions a week. For: IT support staff, networking graduates, career changers with basic computer skills. A laptop with 8 GB RAM is needed for labs.', true)
