INSERT INTO modules (id, domain_id, title, description, tool, order_index) VALUES
  ('a37d7d2f-436e-548f-a375-fc9342c1a665', '85eebe54-039a-56e2-8b66-223a25df396a', 'Security foundations', 'Covers: CIA triad, risk, threats; Security careers and roles; Lab setup (VirtualBox, Kali, Ubuntu). Deliverable: Working home lab.', 'Security', 1),
  ('cd9e39de-e536-5f7b-9cd0-9428fd79b154', '85eebe54-039a-56e2-8b66-223a25df396a', 'Networking', 'Covers: OSI and TCP/IP, subnetting; DNS, DHCP, ports and protocols; Packet analysis with Wireshark. Deliverable: Packet capture analysis.', 'Networking', 2),
  ('947cc010-d342-523a-b9df-f8d52d5aeb4e', '85eebe54-039a-56e2-8b66-223a25df396a', 'Linux and Windows administration', 'Covers: Linux CLI, permissions, processes; Windows, Active Directory basics; PowerShell essentials. Deliverable: Hardened Linux server.', 'Linux', 3),
  ('f7622e97-12ad-541e-90f5-ce58679801fb', '85eebe54-039a-56e2-8b66-223a25df396a', 'Scripting for security', 'Covers: Bash and Python; Parsing logs automatically; Working with APIs (VirusTotal). Deliverable: Log-parser script.', 'Python', 4),
  ('197b0b9d-f0ca-5bb8-95fd-02eee2e079a3', '85eebe54-039a-56e2-8b66-223a25df396a', 'Threats and attacks', 'Covers: Malware, phishing, social engineering; Nigerian patterns: BEC, SIM swap, POS fraud; MITRE ATT&CK. Deliverable: Phishing analysis report.', 'Security', 5),
  ('afa47abf-1428-5c53-9816-576714eec325', '85eebe54-039a-56e2-8b66-223a25df396a', 'Cryptography and identity', 'Covers: Hashing, PKI, TLS; MFA and password policy; Least privilege and IAM. Deliverable: IAM policy for a small firm.', 'Security', 6),
  ('0269fd08-5395-5954-bc3f-6d56202c2619', '85eebe54-039a-56e2-8b66-223a25df396a', 'Network security', 'Covers: Firewalls, VPNs, segmentation; IDS / IPS; pfSense lab. Deliverable: Segmented lab network.', 'Networking', 7),
  ('2258e72b-8438-5fb5-bf83-1417704f5d5b', '85eebe54-039a-56e2-8b66-223a25df396a', 'Vulnerability management', 'Covers: Scanning with Nmap and OpenVAS; CVSS scoring and prioritisation; Patching and reporting. Deliverable: Vulnerability report (mid-course project).', 'Security', 8),
  ('a65c17fd-c61c-5477-a84d-b575d2053961', '85eebe54-039a-56e2-8b66-223a25df396a', 'Web application security', 'Covers: OWASP Top 10; Burp Suite; DVWA and Juice Shop labs. Deliverable: Web app findings report.', 'Security', 9),
  ('7949dbb4-1416-5933-a1b3-cf8b9f9221a4', '85eebe54-039a-56e2-8b66-223a25df396a', 'Ethical hacking methodology', 'Covers: Recon, exploitation, privilege escalation (lab only); Rules of engagement; Law: Cybercrimes Act 2015 (amended 2024). Deliverable: Mini pentest report.', 'Security', 10),
  ('fd598a0a-4a0e-573e-9e8c-507d0cb326a2', '85eebe54-039a-56e2-8b66-223a25df396a', 'Security operations and SIEM', 'Covers: Log sources and ingestion; Writing detection rules; Alert triage and escalation. Deliverable: SIEM dashboard + 5 detections.', 'SIEM', 11),
  ('3cd26a7f-8fe1-550d-924b-5bbb873f2f0d', '85eebe54-039a-56e2-8b66-223a25df396a', 'Incident response and forensics', 'Covers: NIST incident response lifecycle; Playbooks and evidence handling; Disk and memory basics. Deliverable: Incident playbook.', 'Security', 12),
  ('c2113da7-2071-5962-9e97-04b82ddd7314', '85eebe54-039a-56e2-8b66-223a25df396a', 'Cloud security', 'Covers: Shared responsibility model; IAM misconfigurations in AWS / Azure; Microsoft Defender and Sentinel. Deliverable: Cloud misconfiguration audit.', 'Cloud', 13),
  ('377ee5a4-d0ac-54c0-90c4-39ef3ab36268', '85eebe54-039a-56e2-8b66-223a25df396a', 'Governance, risk and compliance', 'Covers: ISO 27001, NIST CSF 2.0; NDPA 2023, CBN cybersecurity framework; Writing policies and risk registers. Deliverable: Risk register + policy.', 'GRC', 14),
  ('884b0eaf-a54f-5e54-aab5-afe54702e179', '85eebe54-039a-56e2-8b66-223a25df396a', 'AI and security', 'Covers: AI phishing and deepfakes; Using AI in the SOC; Securing LLM apps: prompt injection. Deliverable: AI threat brief.', 'AI', 15),
  ('a032c23f-f6c3-57a3-91e9-0c01759b71fb', '85eebe54-039a-56e2-8b66-223a25df396a', 'Capstone and certification prep', 'Covers: Blue-team SOC simulation; Security+ mock exams; Interview practice. Deliverable: SOC simulation report + mock exam score.', 'Capstone', 16)
