-- ── Landing page programme cards ────────────────────────────────────────
INSERT INTO lp_programs (id, title, description, icon, icon_bg, icon_color, level, duration, lessons, skills, cta_href, is_active, sort_order) VALUES
  ('fac8c2ac-5290-5f43-a3e7-963945f94afd', 'AI Automation', 'Design, build and run AI-powered workflows that a Nigerian business can trust: from mapping the process to handing over a monitored, documented automation.', '🤖', '#FCE7F3', '#BE185D', 'Beginner', '10 weeks', '40 lessons', '{"n8n","Prompting","APIs & Webhooks","AI Agents"}', '/auth/register', true, 0),
  ('8ce99386-bdf1-59db-a871-000fc70e4abf', 'Python Programming', 'From first line of code to a deployed, tested Python application, with debugging and code reading practised every single week.', '🐍', '#EDE9FE', '#7C3AED', 'Beginner', '12 weeks', '48 lessons', '{"Python","Git & GitHub","pytest","FastAPI"}', '/auth/register', true, 1),
  ('edd42055-79f3-5dee-a214-5188b9fc1985', 'UI/UX Design', 'Research-led product design for African users, ending with a portfolio of case studies that show reasoning, testing and results.', '🎨', '#FFEDD5', '#C2410C', 'Beginner', '12 weeks', '48 lessons', '{"User Research","Figma","Prototyping","Usability Testing"}', '/auth/register', true, 2),
  ('7c16011c-73a3-5dbf-ba87-21f071b2ea84', 'Public Health Data Analytics', 'Turn routine health data into decisions: quality-checked DHIS2 data, indicator dashboards, and briefs that programme managers actually act on.', '🏥', '#DCFCE7', '#15803D', 'Intermediate', '10 weeks', '40 lessons', '{"DHIS2","Data Quality","Power BI","Epidemiology"}', '/auth/register', true, 3),
  ('a9bae0dd-7bee-5734-9b5a-a11fa27ec167', 'Data Analysis for Accountants', 'Automate month-end, reconcile faster, test full populations and report in Power BI, starting from the Excel skills accountants already use.', '📒', '#FEF9C3', '#A16207', 'Intermediate', '8 weeks', '32 lessons', '{"Power Query","Reconciliations","Power BI","Audit Analytics"}', '/auth/register', true, 4),
  ('2adc1600-da3e-561e-8934-9b5497871f99', 'Data Analysis for Engineers', 'Analyse sensor, process and maintenance data the way plants and utilities need it: SPC, experiments, reliability and early warning of failures.', '⚙️', '#DBEAFE', '#1D4ED8', 'Intermediate', '10 weeks', '40 lessons', '{"Python","SPC","Design of Experiments","Reliability"}', '/auth/register', true, 5),
  ('0d837a79-bacc-522f-80c1-b74c63c5585b', 'Cyber Security', 'A lab-first path to SOC Analyst (Tier 1) and junior security roles, aligned to Security+ and ISC2 CC, with every skill evidenced in a portfolio.', '🛡️', '#E0F2FE', '#0369A1', 'Beginner', '16 weeks', '64 lessons', '{"Linux","Networking","SIEM","Incident Response"}', '/auth/register', true, 6)
